import sys
import threading
from concurrent.futures import ThreadPoolExecutor

import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Run check on every element of xs in parallel using a thread pool.

    Returns the results of check in the same order as xs. If any element is
    bad, raises the Bad of the lowest-index bad element, regardless of which
    thread finishes first. All elements are checked before raising.
    """
    results: list[int] = []
    first_bad: Bad | None = None
    with ThreadPoolExecutor(max_workers=min(32, max(1, len(xs)))) as pool:
        futures = [pool.submit(check, x) for x in xs]
        # Collect in index order; keep going after a failure so every
        # future is awaited and the lowest-index Bad is the one kept.
        for fut in futures:
            try:
                results.append(fut.result())
            except Bad as exc:
                if first_bad is None:
                    first_bad = exc
    if first_bad is not None:
        raise first_bad
    return results


def test_all_even_returns_in_order() -> None:
    assert all_even([2, 4, 6, 8, 0]) == [2, 4, 6, 8, 0]


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_single_bad() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, 4, 5, 6])
    assert ei.value.n == 5


def test_lowest_index_not_lowest_value() -> None:
    with pytest.raises(Bad) as ei:
        all_even([8, 9, 4, 7, 1])
    assert ei.value.n == 9

    with pytest.raises(Bad) as ei2:
        all_even([7, 3])
    assert ei2.value.n == 7


def test_lowest_index_wins_even_if_finishes_last(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    gate = threading.Event()

    def slow_check(x: int) -> int:
        if x == 3:
            # Lowest-index bad element: finishes only after the later one.
            gate.wait(timeout=5)
            raise Bad(3)
        if x == 5:
            try:
                raise Bad(5)
            finally:
                gate.set()
        return x

    monkeypatch.setattr(sys.modules[__name__], "check", slow_check)

    with pytest.raises(Bad) as ei:
        all_even([2, 3, 4, 5, 6])
    assert ei.value.n == 3


def test_all_elements_are_checked_before_raising(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    seen: set[int] = set()
    lock = threading.Lock()

    def recording_check(x: int) -> int:
        with lock:
            seen.add(x)
        if x % 2 == 1:
            raise Bad(x)
        return x

    monkeypatch.setattr(sys.modules[__name__], "check", recording_check)

    with pytest.raises(Bad) as ei:
        all_even([1, 2, 4, 6, 8])
    assert ei.value.n == 1
    assert seen == {1, 2, 4, 6, 8}
